<?php header('Content-Type: application/javascript; charset=utf-8');require_once dirname(__DIR__,2).'/app/config/Conexion.php';require_once dirname(__DIR__,2).'/app/dao/BebidaDAO.php';$productos=(new BebidaDAO(Conexion::obtener()))->listarActivas(); ?>
const products=[<?php foreach($productos as $p): ?>{id:<?= (int)$p['id'] ?>,name:<?= json_encode($p['nombre'],JSON_UNESCAPED_UNICODE) ?>,price:<?= (float)$p['precio'] ?>,stock:<?= (int)$p['stock'] ?>},<?php endforeach; ?>];
const cartKey='bodeguita-cart-v2';let cart=JSON.parse(localStorage.getItem(cartKey)||'[]').flatMap(item=>{const current=products.find(p=>p.id===Number(item.id));return current&&current.stock>0?[{...current,qty:Math.min(Math.max(1,Number(item.qty)||1),current.stock)}]:[]});let selected='todos';const money=n=>new Intl.NumberFormat('es-AR',{style:'currency',currency:'ARS',maximumFractionDigits:0}).format(n);const safe=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function redrawCart(){document.querySelector('#basket-count').textContent=cart.reduce((n,p)=>n+p.qty,0);document.querySelector('#basket-total').textContent=money(cart.reduce((n,p)=>n+p.price*p.qty,0));document.querySelector('#basket-items').innerHTML=cart.length?cart.map(p=>`<div class="basket-row"><div><strong>${safe(p.name)}</strong><br><small>${money(p.price)} · ${p.qty} botella${p.qty===1?'':'s'}</small></div><div class="qty"><button data-change="-1" data-id="${p.id}" aria-label="Quitar una botella">−</button><span>${p.qty}</span><button data-change="1" data-id="${p.id}" aria-label="Agregar una botella">+</button></div></div>`).join(''):'<p class="basket-empty">Todavía no hay botellas por acá.<br>Elegí algo rico para compartir.</p>';localStorage.setItem(cartKey,JSON.stringify(cart))}
function notice(text){const el=document.querySelector('#notice');el.textContent=text;el.classList.add('visible');setTimeout(()=>el.classList.remove('visible'),2600)}function show(id){document.querySelector(id).hidden=false;document.body.style.overflow='hidden'}function hide(id){document.querySelector(id).hidden=true;if(!document.querySelector('.overlay:not([hidden])'))document.body.style.overflow=''}
document.querySelectorAll('.add').forEach(btn=>btn.addEventListener('click',()=>{const product=products.find(p=>p.id===Number(btn.dataset.id));const inCart=cart.find(p=>p.id===product.id);if(inCart&&inCart.qty>=product.stock){notice('Llegaste al stock disponible de esta etiqueta.');return}if(inCart)inCart.qty++;else cart.push({...product,qty:1});redrawCart();filterProducts();notice('Sumamos una botella a tu selección ✳')}));document.querySelector('#basket-open').addEventListener('click',()=>show('#basket-overlay'));document.querySelector('.close').addEventListener('click',()=>hide('#basket-overlay'));document.querySelectorAll('.overlay').forEach(el=>el.addEventListener('click',e=>{if(e.target===el)hide('#'+el.id)}));document.querySelectorAll('.order-close').forEach(b=>b.addEventListener('click',()=>hide('#order-overlay')));document.addEventListener('keydown',e=>{if(e.key==='Escape')document.querySelectorAll('.overlay:not([hidden])').forEach(el=>hide('#'+el.id))});
document.querySelector('#basket-items').addEventListener('click',e=>{const button=e.target.closest('[data-change]');if(!button)return;const product=cart.find(p=>p.id===Number(button.dataset.id));const stock=products.find(p=>p.id===product.id).stock;if(button.dataset.change==='1'&&product.qty>=stock){notice('Llegaste al stock disponible de esta etiqueta.');return}product.qty+=Number(button.dataset.change);if(product.qty<1)cart=cart.filter(p=>p.id!==product.id);redrawCart()});document.querySelector('#share-order').addEventListener('click',()=>{if(!cart.length){notice('Tu selección está vacía.');return}document.querySelector('#order-items').value=JSON.stringify(cart.map(p=>({id:p.id,cantidad:p.qty})));hide('#basket-overlay');show('#order-overlay')});document.querySelector('#order-form').addEventListener('submit',()=>{document.querySelector('#order-items').value=JSON.stringify(cart.map(p=>({id:p.id,cantidad:p.qty})))})
function filterProducts(){const term=document.querySelector('#search').value.trim().toLocaleLowerCase('es');document.querySelectorAll('.product').forEach(card=>{card.hidden=!((selected==='todos'||card.dataset.kind===selected||(selected==='blanco'&&card.dataset.kind==='rosado'))&&card.dataset.search.includes(term))})}const params=new URLSearchParams(location.search);if(params.has('buscar'))document.querySelector('#search').value=params.get('buscar');const requestedType=params.get('tipo');const initialFilter=[...document.querySelectorAll('.filter')].find(button=>button.dataset.filter===requestedType);if(initialFilter){document.querySelector('.filter.active')?.classList.remove('active');initialFilter.classList.add('active');selected=requestedType}document.querySelectorAll('.filter').forEach(button=>button.addEventListener('click',()=>{document.querySelector('.filter.active').classList.remove('active');button.classList.add('active');selected=button.dataset.filter;filterProducts()}));document.querySelector('#search').addEventListener('input',filterProducts);redrawCart();filterProducts();

if(location.hash==='#mi-seleccion')show('#basket-overlay');
